// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAccounts Connection state of GitHub and Jira
	// (GET /api/accounts)
	GetAccounts(ctx context.Context, request GetAccountsRequestObject) (GetAccountsResponseObject, error)
	// DisconnectAccount Remove the stored tokens of a provider
	// (DELETE /api/accounts/{provider})
	DisconnectAccount(ctx context.Context, request DisconnectAccountRequestObject) (DisconnectAccountResponseObject, error)
	// CheckAccount Check a connection with the provider now
	// (POST /api/accounts/{provider}/check)
	CheckAccount(ctx context.Context, request CheckAccountRequestObject) (CheckAccountResponseObject, error)
	// GetActivity The activity log, newest first
	// (GET /api/activity)
	GetActivity(ctx context.Context, request GetActivityRequestObject) (GetActivityResponseObject, error)
	// PutGithubPat Validate and store a GitHub personal access token
	// (PUT /api/github/pat)
	PutGithubPat(ctx context.Context, request PutGithubPatRequestObject) (PutGithubPatResponseObject, error)
	// GetJiraOptions The status names and project keys of the connected Jira site, for the rule form
	// (GET /api/jira/options)
	GetJiraOptions(ctx context.Context, request GetJiraOptionsRequestObject) (GetJiraOptionsResponseObject, error)
	// CompleteOAuth Finish an OAuth authorization with the code and state from the provider redirect
	// (POST /api/oauth/complete)
	CompleteOAuth(ctx context.Context, request CompleteOAuthRequestObject) (CompleteOAuthResponseObject, error)
	// ApprovePr Approve a pull request
	// (POST /api/prs/{id}/approve)
	ApprovePr(ctx context.Context, request ApprovePrRequestObject) (ApprovePrResponseObject, error)
	// MergePr Merge a pull request and move its tickets
	// (POST /api/prs/{id}/merge)
	MergePr(ctx context.Context, request MergePrRequestObject) (MergePrResponseObject, error)
	// MarkPrReady Mark a draft pull request ready for review
	// (POST /api/prs/{id}/ready)
	MarkPrReady(ctx context.Context, request MarkPrReadyRequestObject) (MarkPrReadyResponseObject, error)
	// RequestChangesPr Request changes on a pull request
	// (POST /api/prs/{id}/request-changes)
	RequestChangesPr(ctx context.Context, request RequestChangesPrRequestObject) (RequestChangesPrResponseObject, error)
	// PutPrTickets Set the manual ticket links and the hidden keys of a pull request
	// (PUT /api/prs/{id}/tickets)
	PutPrTickets(ctx context.Context, request PutPrTicketsRequestObject) (PutPrTicketsResponseObject, error)
	// ListRepos Every repository the dashboard has seen, with its merge settings
	// (GET /api/repos)
	ListRepos(ctx context.Context, request ListReposRequestObject) (ListReposResponseObject, error)
	// PutRepos Set the default method and replace the branch rules of several repositories
	// (PUT /api/repos)
	PutRepos(ctx context.Context, request PutReposRequestObject) (PutReposResponseObject, error)
	// GetRepo Merge settings of one repository
	// (GET /api/repos/{id})
	GetRepo(ctx context.Context, request GetRepoRequestObject) (GetRepoResponseObject, error)
	// PutRepo Set the default method and replace the branch rules of a repository
	// (PUT /api/repos/{id})
	PutRepo(ctx context.Context, request PutRepoRequestObject) (PutRepoResponseObject, error)
	// ListRetries Failed transitions waiting for a retry
	// (GET /api/retries)
	ListRetries(ctx context.Context, request ListRetriesRequestObject) (ListRetriesResponseObject, error)
	// DismissRetry Forget a failed transition
	// (DELETE /api/retries/{id})
	DismissRetry(ctx context.Context, request DismissRetryRequestObject) (DismissRetryResponseObject, error)
	// RetryTransition Try a failed transition again
	// (POST /api/retries/{id})
	RetryTransition(ctx context.Context, request RetryTransitionRequestObject) (RetryTransitionResponseObject, error)
	// GetRules The ordered status sync rules
	// (GET /api/rules)
	GetRules(ctx context.Context, request GetRulesRequestObject) (GetRulesResponseObject, error)
	// PutRules Replace the whole ordered list of status sync rules
	// (PUT /api/rules)
	PutRules(ctx context.Context, request PutRulesRequestObject) (PutRulesResponseObject, error)
	// PreviewRule The tickets a rule would move now
	// (POST /api/rules/preview)
	PreviewRule(ctx context.Context, request PreviewRuleRequestObject) (PreviewRuleResponseObject, error)
	// GetSession Session info and CSRF token
	// (GET /api/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// CreateSession Exchange a one-time launch token for a session cookie
	// (POST /api/session)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
	// RevokeAllSessions Sign out every browser, including this one
	// (POST /api/sessions/revoke-all)
	RevokeAllSessions(ctx context.Context, request RevokeAllSessionsRequestObject) (RevokeAllSessionsResponseObject, error)
	// GetSettings Global settings
	// (GET /api/settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// PutSettings Replace the global settings
	// (PUT /api/settings)
	PutSettings(ctx context.Context, request PutSettingsRequestObject) (PutSettingsResponseObject, error)
	// GetSetup Which OAuth apps are configured, and the callback URLs to register
	// (GET /api/setup)
	GetSetup(ctx context.Context, request GetSetupRequestObject) (GetSetupResponseObject, error)
	// PutSetupClient Store the OAuth app client credentials of a provider in the secrets store
	// (PUT /api/setup/{provider})
	PutSetupClient(ctx context.Context, request PutSetupClientRequestObject) (PutSetupClientResponseObject, error)
	// GetSnapshot The latest dashboard snapshot
	// (GET /api/snapshot)
	GetSnapshot(ctx context.Context, request GetSnapshotRequestObject) (GetSnapshotResponseObject, error)
	// SyncNow Start a refresh now
	// (POST /api/sync)
	SyncNow(ctx context.Context, request SyncNowRequestObject) (SyncNowResponseObject, error)
	// GetAssignedTickets Jira tickets assigned to the user, for the ticket picker
	// (GET /api/tickets/assigned)
	GetAssignedTickets(ctx context.Context, request GetAssignedTicketsRequestObject) (GetAssignedTicketsResponseObject, error)
	// GetTransitions Transitions available for a ticket, with the fields they require
	// (GET /api/tickets/{key}/transitions)
	GetTransitions(ctx context.Context, request GetTransitionsRequestObject) (GetTransitionsResponseObject, error)
}

// StrictHandlerFunc and StrictMiddlewareFunc are type aliases rather than
// distinct named types, so middleware written against one generated package
// can be shared with every other generated package using the same framework.
type StrictHandlerFunc = func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc = func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

